mapper.select:
SELECT 
  FROM RAW_ENV_TB
 WHERE RAW_SEQ = #{rawSeq}
   AND DEL_YN = 0

   AND MET_KEY = #{metKey}

 ORDER BY MET_KEY, ROW_NO

SELECT IFNULL(MAX(ROW_NO), 0) + 1
  FROM RAW_ENV_TB
 WHERE RAW_SEQ = #{rawSeq}
   AND MET_KEY = #{metKey}

SELECT REV_YN
  FROM MEMBER_TB
 WHERE ID = #{memId}

SELECT u.ZONE_SEQ, u.SRC AS USE_SRC, u.SEQ AS USE_SEQ, u.TEST_ID AS USE_TEST_ID, u.MET_KEY AS USE_MET_KEY, u.PURPOSE AS USE_PURPOSE, u.MEM_NAME AS USE_MEM_NAME, u.S_DT AS USE_START_DT, u.E_DT AS USE_END_DT FROM ( SELECT 'RAW' AS SRC, e.ENV_SEQ AS SEQ, e.ZONE_SEQ, AS TEST_ID, e.MET_KEY, NULL AS PURPOSE, e.MEM_NAME, e.TEST_S_DT AS S_DT, e.TEST_E_DT AS E_DT FROM RAW_ENV_TB e LEFT JOIN RAW_TB r ON r.RAW_SEQ = e.RAW_SEQ LEFT JOIN TEST_TB t ON t.TEST_SEQ = r.TEST_SEQ LEFT JOIN TEST_ITEM_TB ti ON ti.TEST_ITEM_SEQ = t.TEST_ITEM_SEQ LEFT JOIN JOB_TB j ON j.QUO_YM = ti.QUO_YM AND j.QUO_SEQ = ti.QUO_SEQ WHERE e.ZONE_SEQ = #{zoneSeq} AND e.ENV_SEQ != #{envSeq} AND e.DEL_YN = 0 AND e.MIG_YN = 0 AND e.TEST_S_DT IS NOT NULL
AND e.TEST_S_DT < #{testEDt}
AND (e.TEST_E_DT IS NULL OR e.TEST_E_DT > #{testSDt}) UNION ALL SELECT 'ETC', x.USE_SEQ, x.ZONE_SEQ, NULL, NULL, x.PURPOSE, x.MEM_NAME, x.START_DT, x.END_DT FROM CHAMBER_ETC_USE_TB x WHERE x.ZONE_SEQ = #{zoneSeq} AND x.DEL_YN = 0
AND x.START_DT < #{testEDt}
AND (x.END_DT IS NULL OR x.END_DT > #{testSDt}) ) u ORDER BY u.S_DT LIMIT 1
